return {
    property: "Name", // Default column to search
    operation: "contains", // Default operator
    label: "Name" // Human readable label for the placeholder
}

const displayColumnNames = [
    "Name",
    "Code",
    "Type",
    // "EffectiveFromDate",
    // "EffectiveToDate",
    // "Frequency",
    "Amount",
    "Active",
    "IsTaxable"
];

const displayColumnOptions = {
    valueKey: {
        "Name": "Name"
    },
    type: {
        "Active": "boolean",
        "IsTaxable": "boolean",
        "NeedAttendance": "boolean",
        "EffectiveFromDate": "date",
        "EffectiveToDate": "date",
        "Amount": "currency"
    }
};

return {
    columnKeys: displayColumnNames,
    options: displayColumnOptions
};

return [
    // --- Identifiers ---
    {
        label: "ID",
        value: "Id",
        type: "number",
        // operators: ["eq"]
    },
    {
        label: "Code",
        value: "Code",
        type: "string",
        // operators: ["eq", "contains", "startswith"]
    },

    // --- Core Identity ---
    {
        label: "Name",
        value: "Name",
        type: "string",
        // operators: ["contains", "eq", "startswith"]
    },
    {
        label: "Description",
        value: "Description",
        type: "string",
        // operators: ["contains"]
    },
    {
        label: "Type",
        value: "Type",
        type: "dropdown",
        source: "typeMap",
        operators: ["eq"]
    },
    {
        label: "Active",
        value: "Active",
        type: "boolean",
        operators: ["eq"]
    },

    // --- Configuration ---
    {
        label: "Frequency",
        value: "Frequency",
        type: "dropdown",
        source: "frequencyMap",
        operators: ["eq"]
    },
    {
        label: "Calculation Method",
        value: "CalculationMethodId",
        type: "dropdown",
        source: "calculationMethodMap",
        operators: ["eq"]
    },
    {
        label: "Need Attendance",
        value: "NeedAttendance",
        type: "boolean",
        operators: ["eq"]
    },

    // --- Financials ---
    {
        label: "Amount",
        value: "Amount",
        type: "number",
        // operators: ["eq", "gt", "lt"]
    },
    {
        label: "Is Taxable",
        value: "IsTaxable",
        type: "boolean",
        operators: ["eq"]
    },
    {
        label: "Tax Exemption Amount",
        value: "TaxExemptionAmount",
        type: "number",
        // operators: ["eq", "gt", "lt"]
    },

    // --- Dates ---
    {
        label: "Effective From",
        value: "EffectiveFromDate",
        type: "date",
        // operators: ["eq", "gt", "lt", "ge", "le"]
    },
    {
        label: "Effective To",
        value: "EffectiveToDate",
        type: "date",
        // operators: ["eq", "gt", "lt", "ge", "le"]
    },

    // --- Relationships ---
    {
        label: "Accrual",
        value: "AccrualId",
        type: "dropdown",
        source: "accrualMap",
        operators: ["eq"]
    },
    {
        label: "Currency",
        value: "CurrencyId",
        type: "dropdown",
        source: "currencyMap",
        operators: ["eq"]
    }
];
